<p><span style="text-decoration: underline;"><strong>SJF</strong></span></p>
<p>#include&lt;stdio.h&gt;<br />#include&lt;conio.h&gt;<br />main()<br />{<br />int p[20], bt[20], wt[20], tat[20], i, k, n, temp;<br />float wtavg, tatavg;<br />clrscr();<br />printf("\nEnter the number of processes -- ");<br />scanf("%d", &amp;n);<br />for(i=0;i&lt;n;i++)<br />{<br />p[i]=i;<br />printf("Enter Burst Time for Process %d -- ", i);<br />scanf("%d", &amp;bt[i]);<br />}<br />for(i=0;i&lt;n;i++)<br />for(k=i+1;k&lt;n;k++)<br />if(bt[i]&gt;bt[k])<br />{<br />temp=bt[i];<br />bt[i]=bt[k];<br />bt[k]=temp;<br />temp=p[i];<br />p[i]=p[k];<br />p[k]=temp;<br />}<br />wt[0] = wtavg = 0;<br />tat[0] = tatavg = bt[0];<br />for(i=1;i&lt;n;i++)<br />{<br />wt[i] = wt[i-1] +bt[i-1];<br />tat[i] = tat[i-1] +bt[i];<br />wtavg = wtavg + wt[i];<br />tatavg = tatavg + tat[i];<br />}<br />printf("\n\t PROCESS \tBURST TIME \t WAITING TIME\t TURNAROUND TIME\n");<br />for(i=0;i&lt;n;i++)<br />printf("\n\t P%d \t\t %d \t\t %d \t\t %d", p[i], bt[i], wt[i], tat[i]);<br />printf("\nAverage Waiting Time -- %f", wtavg/n);<br />printf("\nAverage Turnaround Time -- %f", tatavg/n);<br />getch();<br />}</p>